// The page's intonation line, held to the desktop's own summary.
//
// `web/intonation.js` is the one port with no conformity proof of its own: the
// segmenter and the YIN are compared frame by frame, the piano sample by
// sample, the archive through its headers — but this module decides a VISIBLE
// sentence ("3 of 5 notes in tune, 60 %") out of thresholds, and a threshold
// moved on one side changes the line while every other check stays green.
//
// The fixture is generated by `scripts/export_web_fixtures.py` from
// `core.intonation.summarize`, over the traps the line can get wrong: fewer
// notes than MIN_NOTES, a mean under MIN_CENTS, identically-pitched notes (no
// extent to divide into registers), an odd count (the extra note belongs to
// the END half), the two inclusive bars, and an empty take.
//
// Every deviation in it is a WHOLE number of cents, on purpose: the page
// summarises the cents its table PRINTS while the desktop reads the raw float,
// and that difference is a stated policy (a note painted "in tune" must not be
// missing from the in-tune count). Whole cents make both sides read the same
// numbers, so what this file proves is the port's LOGIC — thresholds, bands,
// halves, counts and shares — and nothing else.
import test from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";

import { summarizeIntonation } from "../intonation.js";

const FIXTURE = JSON.parse(
  await readFile(new URL("./intonation.json", import.meta.url), "utf8"),
);

const cases = FIXTURE.cases;
const named = (name) => {
  const found = cases.find((entry) => entry.name === name);
  assert.ok(found, `the fixture lost its ${name} case`);
  return found;
};

/** The desktop rounds to one decimal; the page keeps the mean whole. */
const NEAR = 0.05 + 1e-9;

/** One group: both must stay silent, or name the same size and mean. */
function assertGroup(actual, expected, where) {
  if (expected === null) {
    assert.equal(actual, null, `${where}: the page names a lean the desktop refuses`);
    return;
  }
  assert.ok(actual, `${where}: the page stays silent where the desktop names a lean`);
  assert.equal(actual.n, expected.n, `${where}: ${actual.n} notes, the desktop says ${expected.n}`);
  assert.ok(
    Math.abs(actual.mean - expected.mean_cents) <= NEAR,
    `${where}: the page's mean is ${actual.mean}, the desktop's ${expected.mean_cents}`,
  );
}

test("the page summarises every trap case the way the desktop does", () => {
  assert.ok(cases.length >= 8, `only ${cases.length} cases were frozen`);
  for (const entry of cases) {
    const js = summarizeIntonation(entry.notes);
    const py = entry.summary;
    const where = entry.name;
    assert.equal(js.n, py.n_notes, `${where}: the page counts ${js.n} notes, the desktop ${py.n_notes}`);
    assert.equal(js.tendency, py.tendency, `${where}: the page names "${js.tendency}", the desktop "${py.tendency}"`);
    // The empty take returns NO container from the desktop (its early answer
    // sets both to None), while the page answers three named null bands: the
    // two shapes mean the same silence and are read the same way here.
    const band = (name) => (py.by_register === null ? null : py.by_register[name]);
    const half = (name) => (py.by_position === null ? null : py.by_position[name]);
    for (const name of ["low", "mid", "high"]) {
      assertGroup(js.byRegister[name], band(name), `${where} register ${name}`);
    }
    for (const name of ["start", "end"]) {
      assertGroup(js.byPosition[name], half(name), `${where} position ${name}`);
    }
    if (!py.n_notes) {
      // An empty take: nothing to share, and no invented lean.
      assert.deepEqual([js.inTune, js.share, js.sharp, js.flat], [0, 0, 0, 0], where);
      continue;
    }
    // The desktop freezes the SHARES rounded to two decimals; the page keeps
    // them exact, so the counts are read back through the share rather than
    // through a third copy of the rule.
    assert.equal(js.inTune, Math.round(py.in_tune_share * py.n_notes), `${where}: in-tune count`);
    assert.equal(js.sharp, Math.round(py.sharp_share * py.n_notes), `${where}: sharp count`);
    assert.equal(js.flat, Math.round(py.flat_share * py.n_notes), `${where}: flat count`);
    assert.ok(
      Math.abs(js.inTune + js.sharp + js.flat - py.n_notes) <= 0,
      `${where}: the page's three counts do not add up to its own note count`,
    );
    assert.ok(
      Math.abs(js.share - py.in_tune_share) <= 0.005 + 1e-9,
      `${where}: the page shares ${js.share}, the desktop ${py.in_tune_share}`,
    );
    assert.ok(
      Math.abs(js.mean - py.mean_cents) <= NEAR,
      `${where}: the page's mean is ${js.mean}, the desktop's ${py.mean_cents}`,
    );
  }
});

test("the traps are still traps", () => {
  // A fixture that lost its traps would compare two happy paths forever: this
  // test reads the CASES, not the summary, and refuses a case that stopped
  // being the edge it was written for.
  const short = named("fewer_than_four_notes_never_leans");
  assert.equal(short.notes.length, 3, "the short case is no longer under MIN_NOTES");
  assert.equal(short.summary.tendency, null, "three notes now name a habit");

  const gentle = named("a_mean_under_twelve_cents_is_not_a_habit");
  const gentleMean = gentle.summary.mean_cents;
  assert.ok(Math.abs(gentleMean) < 12, `the gentle case leans ${gentleMean} cents`);
  assert.equal(gentle.summary.tendency, "even", "a mean under 12 cents is no longer 'even'");

  const same = named("identical_pitches_divide_no_register");
  assert.equal(new Set(same.notes.map((note) => note.midi)).size, 1, "the same-pitch case moved");
  for (const band of ["low", "mid", "high"]) {
    assert.equal(same.summary.by_register[band], null, `an identically-pitched take named ${band}`);
  }

  const odd = named("an_odd_count_gives_its_extra_note_to_the_end");
  assert.equal(odd.notes.length % 2, 1, "the odd case is even");
  assert.equal(odd.summary.by_position.start.n, Math.trunc(odd.notes.length / 2), "the odd split moved");
  assert.equal(odd.summary.by_position.end.n, Math.trunc(odd.notes.length / 2) + 1, "the extra note left the end half");

  // and the two inclusive bars, which a `>` would quietly move
  assert.equal(named("exactly_twelve_cents_is_a_habit").summary.tendency, "sharp", "12 cents is no longer a habit");
  assert.equal(named("exactly_ten_cents_is_in_tune").summary.in_tune_share, 1, "10 cents left the in-tune band");
});
